begin;

-- Run the quotes and invoices script (docs/launch/quotes-invoices-production.sql) first: this stops (changing nothing) if it hasn't been.
do $requires$
begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261012000036') then
